# CUDA kernel: depthwise 2‑D convolution (half precision I/O, float accumulation)
# ----------------------------------------------------------------------
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

extern "C" __global__
void depthwise_conv2d_kernel(
    const __half* __restrict__ input,      // (B, C, H, W)
    const __half* __restrict__ weight,     // (C, 1, K, K)
    const __half* __restrict__ bias,       // (C) or nullptr
    __half* __restrict__ output,           // (B, C, H_out, W_out)
    int B,
    int C,
    int H,
    int W,
    int K,
    int stride,
    int padding,
    int H_out,
    int W_out)
{
    // One thread per output element
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = B * C * H_out * W_out;
    if (idx >= total) return;

    // Decode linear index
    int w_out = idx % W_out;
    int t = idx / W_out;
    int h_out = t % H_out;
    t = t / H_out;
    int c = t % C;
    int b = t / C;

    // Compute the top‑left corner of the receptive field
    int h_start = h_out * stride - padding;
    int w_start = w_out * stride - padding;

    // Pointers to the beginning of the current batch/channel
    const __half* in_ptr  = input  + ((b * C + c) * H * W);
    const __half* w_ptr   = weight + (c * K * K);   // weight layout (C,1,K,K)

    float acc = 0.0f;

    // Convolution loop
    for (int ky = 0; ky < K; ++ky) {
        int h_in = h_start + ky;
        if (h_in < 0 || h_in >= H) continue;
        for (int kx = 0; kx < K; ++kx) {
            int w_in = w_start + kx;
            if (w_in < 0 || w_in >= W) continue;
            float i_val = __half2float(in_ptr[h_in * W + w_in]);
            float w_val = __half2float(w_ptr[ky * K + kx]);
            acc += i_val * w_val;
        }
    }

    // Add bias if present
    if (bias != nullptr) {
        acc += __half2float(bias[c]);
    }

    // Write back as half
    output[idx] = __float2half(acc);
}

torch::Tensor depthwise_conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    const int B = input.size(0);
    const int C = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);
    const int K = weight.size(2);   // (C,1,K,K)

    const int H_out = (H + 2 * padding - K) / stride + 1;
    const int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({B, C, H_out, W_out}, input.options());

    const int total = B * C * H_out * W_out;
    const int threads = 256;
    const int blocks = (total + threads - 1) / threads;

    const __half* in_ptr   = reinterpret_cast<const __half*>(input.data_ptr<at::Half>());
    const __half* w_ptr    = reinterpret_cast<const __half*>(weight.data_ptr<at::Half>());
    const __half* b_ptr    = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        b_ptr = reinterpret_cast<const __half*>(bias.data_ptr<at::Half>());
    }
    __half* out_ptr = reinterpret_cast<__half*>(output.data_ptr<at::Half>());

    depthwise_conv2d_kernel<<<blocks, threads>>>(
        in_ptr, w_ptr, b_ptr, out_ptr,
        B, C, H, W,
        K,
        stride,
        padding,
        H_out,
        W_out
    );

    return output;
}
